'use strict';

// MODULES //

var logger = require( 'debug' );
var parseJSON = require( '@stdlib/utils/parse-json' );
var trim = require( '@stdlib/string/trim' );
var format = require( '@stdlib/string/format' );
var diagnostic = require( './diagnostic.js' );


// VARIABLES //

var debug = logger( 'markdown-to-semantic-document:directive' );


// FUNCTIONS //

/**
* Splits a comma-separated configuration while respecting JSON strings and objects.
*
* @private
* @param {string} value - configuration string
* @returns {Array} configuration fields
*/
function fields( value ) {
	var escaped = false;
	var quote = false;
	var depth = 0;
	var start = 0;
	var out = [];
	var ch;
	var i;

	// Split only at top-level commas. Run configuration values may themselves be JSON arrays, objects, or quoted strings containing commas...
	for ( i = 0; i < value.length; i++ ) {
		ch = value.charAt( i );
		if ( escaped ) {
			// An escaped quote cannot end the current JSON string...
			escaped = false;
			continue;
		}
		if ( quote && ch === '\\' ) {
			escaped = true;
			continue;
		}
		if ( ch === '"' ) {
			quote = !quote;
			continue;
		}
		if ( !quote ) {
			// Track aggregate object/array depth; commas are separators only at depth 0...
			if ( ch === '{' || ch === '[' ) {
				depth += 1;
			} else if ( ch === '}' || ch === ']' ) {
				depth -= 1;
			} else if ( ch === ',' && depth === 0 ) {
				out.push( trim( value.slice( start, i ) ) );
				start = i + 1;
			}
		}
	}
	out.push( trim( value.slice( start ) ) );
	debug( 'Split run configuration: fields=%d', out.length );
	return out;
}

/**
* Parses a run configuration string.
*
* @private
* @param {string} value - configuration string
* @returns {(Object|null)} parsed configuration
*/
function parseRun( value ) {
	var parts;
	var out;
	var idx;
	var key;
	var o;
	var i;

	parts = fields( value );
	out = Object.create( null );

	// Parse each value independently as JSON. This gives directives a compact `key: value` syntax without inventing value coercion rules...
	for ( i = 0; i < parts.length; i++ ) {
		if ( parts[ i ] === '' ) {
			continue;
		}
		idx = parts[ i ].indexOf( ':' );
		if ( idx === -1 ) {
			debug( 'Unable to parse run configuration: missing field delimiter.' );
			return null;
		}
		key = trim( parts[ i ].slice( 0, idx ) );
		if ( key === '' ) {
			debug( 'Unable to parse run configuration: empty field name.' );
			return null;
		}
		o = parseJSON( trim( parts[ i ].slice( idx+1 ) ) );
		if ( o instanceof Error ) {
			debug( 'Unable to parse run configuration: invalid JSON value.' );
			return null;
		}
		out[ key ] = o;
	}
	debug( 'Parsed run configuration: fields=%d', parts.length );
	return out;
}


// MAIN //

/**
* Creates a directive resource.
*
* @private
* @param {Object} state - conversion state
* @param {Object} node - source MDAST node
* @param {Object} classification - HTML classification
* @returns {Object} directive resource
*/
function directive( state, node, classification ) {
	var parsed;
	var family;
	var out;
	var id;

	parsed = null;
	id = format( 'directive[%s]', state.document.resources.directives.length );

	// Normalize the characterized HTML forms to a small family vocabulary. Every recognized directive applies only to the immediately following standalone code block...
	if ( classification.type === 'run-disable' ) {
		family = 'run-disable';
		parsed = {
			'disabled': true
		};
	} else if ( classification.type === 'run' ) {
		family = 'run';
		parsed = parseRun( classification.value );

		// Preserve malformed directives as resources so that accounting remains complete, while exposing the parse failure as a diagnostic...
		if ( parsed === null ) {
			diagnostic( state, 'error', 'malformed-directive', 'Unable to parse run directive.', node, {
				'raw': classification.raw
			});
		}
	} else {
		family = 'eslint';
		parsed = {
			'action': classification.action,
			'value': classification.value
		};
	}
	out = {
		'id': id,
		'family': family,
		'raw': node.value,
		'parsed': parsed,
		'scope': 'next-code',
		'targetRefs': [],
		'source': state.provenance.source( [ node ] )
	};
	debug( 'Created directive resource: id=%s family=%s scope=%s parsed=%s', out.id, out.family, out.scope, out.parsed !== null );
	return out;
}


// EXPORTS //

module.exports = directive;
